mapper.select:
SELECT notification_id, notification_type, title, content, read_at, created_at
FROM notification
WHERE customer_id = #{customerId}
ORDER BY notification_id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO notification (
    customer_id, notification_type, title, content, related_type, related_id, created_at
) VALUES (
    #{customerId}, 'SETTLEMENT_FINALIZED', #{title}, #{content},
    'SETTLEMENT_BATCH', #{batchId}, #{completedAt}
)

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM notification
    WHERE customer_id = #{customerId} AND notification_type = 'SETTLEMENT_FINALIZED'
      AND related_type = 'SETTLEMENT_BATCH' AND related_id = #{batchId}
)

mapper.update:
UPDATE notification
SET read_at = #{readAt}
WHERE customer_id = #{customerId}
  AND read_at IS NULL
